"""Configurable, advisory-only vision model adapter."""

import base64
from typing import Any, Literal

import httpx
from pydantic import BaseModel, Field

from app.config import Settings, get_settings
from app.errors import ConfigurationError, ProviderError
from app.retry import retry_async

PLANT_IMAGE_DISCLAIMER = (
    "Visual output is an advisory observation generated by a configurable model; "
    "it is not a confirmed plant diagnosis. Confirm with local agronomist review "
    "or laboratory testing before acting."
)


class VisionObservation(BaseModel):
    status: Literal["ok", "unavailable"] = "unavailable"
    model: str = ""
    provider: str = "none"
    observations: str = ""
    limitations: list[str] = Field(default_factory=list)
    advisory: bool = True


class VisionModelClient:
    """HTTP vision adapter that returns observations, never diagnoses."""

    def __init__(self, settings: Settings | None = None) -> None:
        self.settings = settings or get_settings()

    async def observe(
        self,
        content: bytes,
        mime_type: str,
        *,
        question: str = "",
        is_plant_image: bool = False,
    ) -> VisionObservation:
        if self.settings.vision_provider == "none":
            return VisionObservation(
                status="unavailable",
                provider="none",
                observations="",
                limitations=[
                    "Vision model is not configured; no visual observation was generated.",
                    PLANT_IMAGE_DISCLAIMER if is_plant_image else "No visual interpretation was performed.",
                ],
            )
        if not self.settings.vision_base_url or not self.settings.vision_model:
            raise ConfigurationError("HTTP vision provider requires a base URL and model.")
        data_url = f"data:{mime_type};base64,{base64.b64encode(content).decode('ascii')}"
        instruction = (
            "Describe only visible agricultural evidence. Do not diagnose, prescribe "
            "treatment, invent confidence scores, or claim scientific validation."
        )
        if is_plant_image:
            instruction += " State explicitly that observations are not a confirmed diagnosis."
        prompt = f"{instruction}\nQuestion: {question or 'Describe visible evidence.'}"
        payload: dict[str, Any] = {
            "model": self.settings.vision_model,
            "messages": [
                {"role": "system", "content": instruction},
                {
                    "role": "user",
                    "content": [
                        {"type": "text", "text": prompt},
                        {"type": "image_url", "image_url": {"url": data_url}},
                    ],
                },
            ],
            "max_tokens": 512,
            "temperature": 0.1,
        }
        headers = {"content-type": "application/json"}
        api_key = self.settings.vision_api_key.get_secret_value()
        if api_key:
            headers["authorization"] = f"Bearer {api_key}"

        async def operation() -> httpx.Response:
            async with httpx.AsyncClient(timeout=self.settings.vision_timeout_seconds) as client:
                return await client.post(
                    f"{self.settings.vision_base_url.rstrip('/')}/chat/completions",
                    json=payload,
                    headers=headers,
                )

        try:
            response = await retry_async(
                operation,
                max_attempts=self.settings.retry_max_attempts,
                base_delay_seconds=self.settings.retry_base_delay_seconds,
                max_delay_seconds=self.settings.retry_max_delay_seconds,
            )
            if response.status_code >= 400:
                raise ProviderError(
                    "Vision model rejected the request.",
                    details={"status": response.status_code},
                )
            body = response.json()
            text = str(body["choices"][0]["message"]["content"])
        except ProviderError:
            raise
        except Exception as error:  # noqa: BLE001 - third-party adapter boundary
            raise ProviderError(
                "Vision model request failed.",
                details={"reason": type(error).__name__},
            ) from error
        limitations = [
            "Model-generated visual observation; not verified evidence.",
            PLANT_IMAGE_DISCLAIMER if is_plant_image else "No claim of scientific validation is made.",
        ]
        return VisionObservation(
            status="ok",
            model=str(body.get("model", self.settings.vision_model)),
            provider="http",
            observations=text[: self.settings.vision_max_chars].strip(),
            limitations=limitations,
        )

    def describe(self) -> dict[str, Any]:
        return {
            "provider": self.settings.vision_provider,
            "model": self.settings.vision_model,
            "configured": self.settings.vision_provider == "none"
            or bool(self.settings.vision_base_url and self.settings.vision_model),
            "credentialsInResponse": False,
            "diagnosisClaims": False,
            "disclaimer": PLANT_IMAGE_DISCLAIMER,
        }


__all__ = ["PLANT_IMAGE_DISCLAIMER", "VisionModelClient", "VisionObservation"]
